-- HU-06/T4a: evidences attached to reports. Database model and security only:
-- the Storage bucket and the endpoints belong to HU-06/T4.
-- Limits mirror web/src/lib/evidences/rules.ts; change both together.
create table public.report_evidences (
  -- Generated by the server before storing the file: it is part of the path.
  id uuid constraint report_evidences_pkey primary key,

  report_id uuid not null,
  uploaded_by uuid not null,

  storage_path text not null,
  original_name text not null,
  mime_type text not null,
  size_bytes integer not null,
  sha256 text not null,
  moderation_status text not null default 'visible',

  created_at timestamptz not null default now(),

  -- RESTRICT: deleting rows would leave orphan objects in Storage.
  constraint report_evidences_report_fkey foreign key (report_id)
    references public.reports (id) on update restrict on delete restrict,

  constraint report_evidences_uploader_fkey foreign key (uploaded_by)
    references public.profiles (id) on update restrict on delete restrict,

  constraint report_evidences_storage_path_key unique (storage_path),

  -- The same content counts once per report (credibility, HU-09).
  -- Its leading column also serves lookups by report.
  constraint report_evidences_report_sha256_key unique (report_id, sha256),

  -- Allow list of rules.ts (no PDF), already lower case.
  constraint report_evidences_mime_type_check check (
    mime_type in ('image/png', 'image/jpeg', 'image/webp')
  ),

  -- EVIDENCE_MAX_FILE_BYTES = 10 MiB.
  constraint report_evidences_size_bytes_check check (
    size_bytes between 1 and 10485760
  ),

  constraint report_evidences_sha256_check check (sha256 ~ '^[0-9a-f]{64}$'),

  constraint report_evidences_moderation_status_check check (
    moderation_status in ('visible', 'hidden')
  ),

  -- Same name rules as rules.ts, plus NFC. Shown to users, never used as a path.
  constraint report_evidences_original_name_check check (
    char_length(original_name) between 1 and 255
    and original_name ~ '[^[:space:]]'
    and original_name !~ '[\u0001-\u001f\u007f-\u009f‪-‮⁦-⁩/\\]'
    and original_name !~ '^\.'
    and original_name !~ '[. ]$'
    and original_name is nfc normalized
  ),

  -- Server-generated object name in the report-evidences bucket:
  -- {uploaded_by}/{report_id}/{id}.{canonical extension}. The first folder is
  -- the owner, which is what the storage.objects policies check.
  constraint report_evidences_storage_path_check check (
    storage_path = uploaded_by::text || '/' || report_id::text || '/'
      || id::text || '.'
      || case mime_type
           when 'image/png' then 'png'
           when 'image/jpeg' then 'jpg'
           when 'image/webp' then 'webp'
         end
  )
);

-- Serves the per-collaborator limit and lookups by uploader.
create index report_evidences_uploaded_by_report_idx
  on public.report_evidences (uploaded_by, report_id);

-- EVIDENCE_MAX_FILES (5) evidences per collaborator and report, hidden ones
-- included. Definer so that rows hidden by RLS are counted; the advisory lock
-- serialises concurrent inserts of the same collaborator in the same report.
create function private.enforce_report_evidences_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- An API user can only insert in their own name (RLS). Skipping other
  -- uploaders avoids revealing their count before RLS rejects the row.
  if auth.uid() is not null and new.uploaded_by is distinct from auth.uid() then
    return new;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(new.uploaded_by::text || '/' || new.report_id::text, 0)
  );

  if (select count(*) from public.report_evidences e
      where e.uploaded_by = new.uploaded_by
        and e.report_id = new.report_id) >= 5 then
    raise exception 'EVIDENCE_TOO_MANY'
      using errcode = 'check_violation',
            detail = 'A collaborator can add at most 5 evidences to a report.';
  end if;

  return new;
end;
$$;

revoke all on function private.enforce_report_evidences_limit()
  from public, anon, authenticated, service_role;

create trigger report_evidences_enforce_limit
  before insert on public.report_evidences
  for each row execute function private.enforce_report_evidences_limit();

alter table public.report_evidences enable row level security;

-- Any active collaborator adds evidences, in their own name, to any report
-- they can read (also reports by other authors). The report condition
-- delegates to the RLS of public.reports.
create policy report_evidences_insert_own_active
  on public.report_evidences for insert to authenticated
  with check (
    uploaded_by = (select auth.uid())
    and moderation_status = 'visible'
    and exists (
      select 1 from public.profiles p
      where p.id = (select auth.uid()) and p.is_active
    )
    and exists (
      select 1 from public.reports r where r.id = report_id
    )
  );

-- Readable when not hidden and its report is readable; active admins see
-- every evidence so they can moderate it.
create policy report_evidences_select_visible
  on public.report_evidences for select to authenticated
  using (
    (
      moderation_status = 'visible'
      and exists (
        select 1 from public.reports r where r.id = report_id
      )
    )
    or exists (
      select 1 from public.profiles p
      where p.id = (select auth.uid()) and p.is_active and p.role_code = 'admin'
    )
  );

-- Only active admins change moderation_status (the only updatable column).
create policy report_evidences_update_moderation_admin
  on public.report_evidences for update to authenticated
  using (
    exists (
      select 1 from public.profiles p
      where p.id = (select auth.uid()) and p.is_active and p.role_code = 'admin'
    )
  )
  with check (
    exists (
      select 1 from public.profiles p
      where p.id = (select auth.uid()) and p.is_active and p.role_code = 'admin'
    )
  );

-- Handlers run as authenticated with the user's Bearer token; no access for
-- anon or service_role. No direct deletion: hiding is the moderation tool.
revoke all on table public.report_evidences
  from public, anon, authenticated, service_role;
grant select on table public.report_evidences to authenticated;
grant insert (id, report_id, uploaded_by, storage_path, original_name,
              mime_type, size_bytes, sha256)
  on table public.report_evidences to authenticated;
grant update (moderation_status) on table public.report_evidences to authenticated;
